sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;700;800&family=Share+Tech+Mono&family=DM+Sans:wght@300;400;500&display=swap');

.nx-hero {
  padding: 80px 60px 72px;
  position: relative;
  overflow: hidden;
  background: #08080f;
  border-bottom: 1px solid rgba(184,122,255,0.12);
}
.nx-hero-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(184,122,255,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(184,122,255,0.04) 1px, transparent 1px);
  background-size: 48px 48px;
  pointer-events: none;
}
.nx-hero::before {
  content: ''; position: absolute;
  width: 700px; height: 500px; border-radius: 50%;
  background: radial-gradient(circle, rgba(184,122,255,0.08) 0%, transparent 65%);
  top: -160px; right: -100px; pointer-events: none;
}
.nx-hero::after {
  content: ''; position: absolute;
  width: 360px; height: 360px; border-radius: 50%;
  background: radial-gradient(circle, rgba(255,184,153,0.05) 0%, transparent 65%);
  bottom: -80px; left: 80px; pointer-events: none;
}
.nx-hero-content {
  position: relative; z-index: 2;
  max-width: 680px;
  animation: nxFadeUp 0.7s ease both;
}
.nx-eyebrow {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.68rem; letter-spacing: 0.35em;
  color: #b87aff; text-transform: uppercase;
  margin-bottom: 22px; display: flex;
  align-items: center; gap: 12px;
}
.nx-eyebrow::before {
  content: ''; display: inline-block;
  width: 20px; height: 1px;
  background: #b87aff; opacity: 0.6;
}
.nx-hero h1 {
  font-family: 'Syne', sans-serif;
  font-size: 4.4rem; font-weight: 800;
  line-height: 1.05; color: #f0ecff;
  margin-bottom: 22px;
}
.nx-accent {
  color: #b87aff;
  text-shadow: 0 0 32px rgba(184,122,255,0.45);
}
.nx-dot { color: #ffb899; }
.nx-sub {
  font-size: 1rem; color: rgba(240,236,255,0.55);
  font-weight: 300; max-width: 460px;
  line-height: 1.75; margin-bottom: 42px;
}
.nx-actions { display: flex; gap: 16px; align-items: center; flex-wrap: wrap; }
.nx-btn-primary {
  display: inline-flex; align-items: center; gap: 10px;
  background: transparent;
  border: 1.5px solid #b87aff; color: #b87aff;
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.75rem; letter-spacing: 0.18em;
  text-transform: uppercase; padding: 15px 32px;
  border-radius: 4px; text-decoration: none;
  transition: all 0.3s;
  box-shadow: 0 0 18px rgba(184,122,255,0.1);
}
.nx-btn-primary:hover {
  background: rgba(184,122,255,0.14);
  box-shadow: 0 0 32px rgba(184,122,255,0.25);
  color: #b87aff; text-decoration: none;
  transform: translateY(-1px);
}
.nx-btn-ghost {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.7rem; letter-spacing: 0.15em;
  text-transform: uppercase; color: rgba(240,236,255,0.28);
  text-decoration: none; transition: color 0.3s;
}
.nx-btn-ghost:hover { color: rgba(240,236,255,0.55); text-decoration: none; }
@keyframes nxFadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
@media (max-width: 768px) {
  .nx-hero { padding: 48px 24px; }
  .nx-hero h1 { font-size: 2.6rem; }
}

